from taf.rfrl.l3_call.core.call_manager_core import CallManagerCore
from taf.rfrl.l3_call.logger.l3_call_logger import log_input_and_output, log_operation, log_result, log_to_console, \
    log_warning
from taf.rfrl.l3_call.enviornment.env_factory import EnvFactory
from taf.rfrl.l3_call.ue.ue import Ue
from taf.rfrl.l3_call.connection.ssh_connection.ssh_connection_factory import SshConnectionFactory
from taf.rfrl.l3_call.attenuator.attenuator import Attenuator
from taf.rfrl.l3_call.exceptions import MissingReservedUE


class CallManager(CallManagerCore):
    @log_input_and_output
    def configure_env(self, logs_path, ue_network_modes=None, attach_should_be_possible=True):
        """
        Environment configuration depending on the determined setup mode

        :param logs_path: path to the desired log location
        :type logs_path: str
        :param ue_network_modes: desired network modes on UEs with specified serial numbers; defaults to None
                                 (current modes set on UEs will be used). Please remember to set the correct value for
                                 network_mode_switch_method in testline configuration file, currently available:
                                 “adb”, “keyevents”, “secretcode”; default "adb"
        :type ue_network_modes:  dict(str, str) e.g. {"SN1234": "NR_only", "SN321": "LTE_only}. Note: available options
                                 to set a strongly depends on UE model and android version, some UE requires "LTE only",
                                 "NR only"
        :param attach_should_be_possible: stating if attach to called cell should succeed, if False but
                                          ue_network_modes param is passed, then network mode will be
                                          assigned to attribute but not changed on UEs as change of network
                                          mode requires successful attach afterward; defaults to True
        :type attach_should_be_possible: bool
        """
        if self.ues:
            log_operation("Environment configuration started..")

            if ue_network_modes:
                self._handle_network_mode(ue_network_modes=ue_network_modes,
                                          attach_should_be_possible=attach_should_be_possible)

            self.logs_path = logs_path
            self.env = EnvFactory.create_environment(ran=self.ran, mode=self.mode, node=self.node)
            self.ssh = SshConnectionFactory.create_connection(ran=self.ran, node=self.node)
            self.ssh.connect_to()
            self.env.open_api_connection()

            log_result("Environment configuration successful")
        else:
            raise MissingReservedUE("In order to execute L3 Call, at least one UE needs to be reserved!"
                                    " Please make sure that you are using 'UE Reservation' keyword in test setup!")

    def clean_up_env(self):
        """
        Cleans up the environment after finished execution of L3 Call
        in particular responsible for unblocking and unbarring all cells,
        closing SSH connection and deleting Env() instance.
        """
        if self.env:
            self.env.clean_up_after_call()
            self.ssh.stop_tcpdump()
            self.ssh.close_connection()

            log_result("All cells made callable, SSH connection closed")
            self.env = None

        if self._attenuator:
            self._set_all_attenuator_ports_to_chosen_mode(mode="ON")

    @log_input_and_output
    def configure_ues(self, ues, reboot=False, access_point_names=None, attenuator_info=False,
                      attenuator_config=False, ue_network_modes=None):
        """
        Configures given ues before L3Call execution
        :param ues: list of UEs from init file
        :type ues: list(Ue)
        :param reboot: should UE reboot be preformed during reservation,
        defaults to False, other options: adb, ute
        :type reboot Union(bool, str)
        :param access_point_names: pairs of UE serial numbers and APNs
        :type access_point_names: dict
        :param attenuator_info: object containing info about attenuator from init file
        :type attenuator_info: object of attenuator producer class, e.g. TopYoung
        :param attenuator_config: configuration of attenuator ports
        :type attenuator_config: dict
        :param ue_network_modes: desired network modes on UEs with specified serial numbers; defaults to None
                                 (current modes set on UEs will be used). Please remember to set the correct value for
                                 network_mode_switch_method in testline configuration file, currently available:
                                 “adb”, “keyevents”, “secretcode”; default "adb"
        :type ue_network_modes:  dict(str, str) e.g. {"SN1234": "NR_only", "SN321": "LTE_only}. Note: available options
                                 to set a strongly depends on UE model and android version, some UE requires "LTE only",
                                 "NR only"
        """
        self.ues = [Ue(ue_index=ue_index, ue=ue) for ue_index, ue in enumerate(ues, start=1)]

        if attenuator_info and attenuator_config:
            self._attenuator = Attenuator(info=attenuator_info, config=attenuator_config)
            self._set_all_attenuator_ports_to_chosen_mode(mode="ON")

        if ue_network_modes:
            self._handle_network_mode(ue_network_modes=ue_network_modes, attach_should_be_possible=True)

        for ue in self.ues:
            ue.reservation(reboot=reboot)

            if access_point_names:
                for serial_number, apn in access_point_names.items():
                    if ue.serial_number == serial_number:
                        ue.set_apn(apn)

        log_result("All UEs configured properly!")

    def perform_ue_attach(self, called_cell, ue_network_modes=None):
        """
        Performs attach procedure on UEs to the given cell.

        :param called_cell: configuration distname of cell on which attach will be performed
        :type called_cell: str
        :param ue_network_modes: desired network modes on UEs with specified serial numbers; defaults to None
                                 (current modes set on UEs will be used). Please remember to set the correct value for
                                 network_mode_switch_method in testline configuration file, currently available:
                                 “adb”, “keyevents”, “secretcode”; default "adb"
        :type ue_network_modes:  dict(str, str) e.g. {"SN1234": "NR_only", "SN321": "LTE_only}. Note: available options
                                 to set a strongly depends on UE model and android version, some UE requires "LTE only",
                                 "NR only"
        """
        log_to_console("Executing attach to cell {} using UEs with serial numbers: {}".format(
            called_cell, [ue.serial_number for ue in self.ues])
        )

        cell_ue_settings = {called_cell: {"ues": ue_network_modes}}
        self.env.called_cells_distnames = [called_cell]
        cell_ids = self.env.cell_ids

        self.env.prepare_setup_to_call()
        self._set_proper_ue_settings_before_attach(throughput=cell_ue_settings,
                                                   cell_id=cell_ids[called_cell]["{}_cell".format(self.node)])

        for ue in self.ues:
            self._remote_tcpdump_path[ue.alias] = self._perform_attach(attach_should_be_possible=True, ue=ue)
            self._verify_cell_id(cell_ids=cell_ids, called_cell=called_cell, ue=ue)
            self.env.handle_beamforming()

            log_to_console("Success! Attach procedure to cell {} executed "
                           "properly on UE with SN {}".format(called_cell, ue.serial_number))

        log_to_console("Attach to cell: {} executed on all UEs".format(called_cell))

    def perform_ue_detach(self, called_cell):
        """
        Performs detach procedure on UEs from the given cell. This method can only be called after executing
        perform_ue_attach method on the same cell.

        :param called_cell: configuration distname of cell from which detach will be performed
        :type called_cell: str
        """
        log_to_console("Executing detach from cell {} using UEs with serial numbers: {}".format(
            called_cell, [ue.serial_number for ue in self.ues])
        )

        for ue in self.ues:
            local_pcap_path = self.logs_path + "/log_{}_{}.pcap".format(called_cell.split("/")[-1], ue.alias)
            self.ssh.stop_tcpdump_collection_and_download_logs(local_path=local_pcap_path,
                                                               remote_path=self._remote_tcpdump_path[ue.alias])
            ue.detach()
            self.env.verify_pcap(cell_distname=called_cell, pcap_path=local_pcap_path, attach_should_be_possible=True)

            log_to_console("Success! Detach procedure from cell {} executed "
                           "properly on UE with SN {}".format(called_cell, ue.serial_number))

        self.env.clean_up_after_call(close_connection_to_bts=False)
        log_to_console("Detach from cell: {} executed on all UEs".format(called_cell))

    @log_input_and_output
    def make_l3_call(self, called_cell, duration, throughput, protocol, udp_buffer="4M", attach_should_be_possible=True,
                     prepare_cells_to_call=True, tput_verification_via_btslog=False, ignored_cells_on_preparation=None):
        """
        Method responsible for performing L3 Call on a given cell and all UEs configured in configure_ue
        in test setup.
        Check will be performed before the L3 Call procedure to make sure that called_cell is callable in a physical
        sense. If called_cell turns out to be uncallable, L3 Call will not be performed and
        warning will be logged.

        There are two possible scenarios:
            * attach_should_be_possible=True (default) -> used when we want test if attach succeeds on
             a given called_cell.
            In that case, attach is performed proceeded by verification that UE was attached to the correct cell.
            After that data transfer in both directions is tested with using duration, throughput, protocol
             and udp_buffer parameters. The last step is verification if all mandatory msgs are present in pcap file.
             This procedure is repeated for each of the UEs passed during UE configuration from test_setup.

            * attach_should_be_possible=False -> used when we want to test whether it is impossible to
             perform attach to the given called_cell (might be used for example in test case where we block cell and
             want to make sure that it is uncallable after that operation).
             In that case attach is attempted, proceeded by verification of pcap file confirming than none l3 call
             msgs were found.
             This procedure is repeated for each of the UEs passed during UE configuration from test_setup.

        :param called_cell: configuration distname of cell for which L3 call will be performed
        :type called_cell: str
        :param duration: duration of data transfer test (one for both directions), i.e. '30s', 30
        :type duration: Union[str, int]
        :param throughput: dictionary containing information about max tputs for each cell along with deviation
            For example:
                    throughputs = {
                                     '827736065':
                                          {
                                              'throughput':
                                                  {
                                                      'downlink': '100 Mbits/sec',
                                                      'uplink': '15 Mbits/sec'
                                                  },
                                              'deviation': '90%'
                                          },
                                    }
        :type throughput: dict
        :param protocol: data transfer protocol; defaults to UDP.
        :type protocol: str
        :param udp_buffer: monitoring data buffer; defaults to 4M.
        :type udp_buffer: str
        :param attach_should_be_possible: stating if attach to called_cell should succeed
        :type attach_should_be_possible: bool
        :param prepare_cells_to_call: should environment be prepared to call, if so, all cells
                                      apart from the called one will be either barred or blocked
        :type prepare_cells_to_call: bool
        :param tput_verification_via_btslog: should average data transfer verification be performed using btslog,
                                         defaults to False, meaning that by default verification will be performed
                                         using iperf throughput verification
        :type tput_verification_via_btslog: bool
        :param ignored_cells_on_preparation: SHOULD BE USED WITH `prepare_cells_to_call` set to True!
                                             list of cells CONFIGURATION distnames that should be ignored during
                                             L3 Call not called cells preparation procedure and not be blocked/barred
        :type ignored_cells_on_preparation: list[str]
        """
        if self.env.is_callable(cell_distname=called_cell):
            if attach_should_be_possible:
                self._make_l3_call_attach_should_be_possible(
                    called_cell=called_cell, ignored_cells_on_preparation=ignored_cells_on_preparation,
                    duration=duration, throughput=throughput, protocol=protocol, udp_buffer=udp_buffer,
                    prepare_cells_to_call=prepare_cells_to_call,
                    tput_verification_via_btslog=tput_verification_via_btslog)

            if not attach_should_be_possible:
                self._make_l3_call_attach_should_not_be_possible(
                    called_cell=called_cell,
                    ignored_cells_on_preparation=ignored_cells_on_preparation,
                    prepare_cells_to_call=prepare_cells_to_call
                )
        else:
            log_warning("Given called_cell {} is not callable, "
                        "L3 Call procedure will NOT be performed!".format(called_cell))

    @log_input_and_output
    def make_parallel_l3_call(self, called_cell, duration, throughput, protocol="udp", udp_buffer="4M",
                              ignored_cells_on_preparation=None):
        """
        Method responsible for performing parallel L3 call procedure i.e. performing attach and
        testing data transfer to called_cell using more than one UE simultaneously.

        :param called_cell: configuration distname of cell for which L3 call will be performed
        :type called_cell: str
        :param duration: duration of data transfer test (one for both directions), i.e. '30s', 30
        :type duration: Union[str, int]
        :param throughput: dictionary containing information about max tputs for each cell along with deviation
            For example:
                    throughputs = {
                                     '827736065':
                                          {
                                              'throughput':
                                                  {
                                                      'downlink': '100 Mbits/sec',
                                                      'uplink': '15 Mbits/sec'
                                                  },
                                              'deviation': '90%'
                                          },
                                    }
        :type throughput: dict
        :param protocol: data transfer protocol; defaults to udp.
        :type protocol: str
        :param udp_buffer: monitoring data buffer; defaults to 4M.
        :type udp_buffer: str
        :param ignored_cells_on_preparation: SHOULD BE USED WITH `prepare_cells_to_call` set to True!
                                             list of cells CONFIGURATION distnames that should be ignored during
                                             L3 Call not called cells preparation procedure and not be blocked/barred
        :type ignored_cells_on_preparation: list[str]
        """
        log_to_console("Executing Parallel L3 call test using UEs with serial "
                       "numbers: {}".format([ue.serial_number for ue in self.ues]))

        self.env.called_cells_distnames = [called_cell]
        if ignored_cells_on_preparation:
            self.env.ignored_cells_distnames = ignored_cells_on_preparation
        cell_ids = self.env.cell_ids
        self.env.prepare_setup_to_call()

        deviation, dl_throughput, ul_throughput = self._prepare_data_transfer_variables(
            cell_id=str(cell_ids[called_cell]["{}_cell".format(self.node)]), throughput=throughput)

        local_pcap_path = self.logs_path + "/log_parallel_{}.pcap".format(called_cell.split("/")[-1])
        remote_tcpdump_path = self.ssh.start_tcpdump_and_get_filepath()

        self._attach_all_ues_and_execute_parallel_data_transfer_in_both_directions(dl_throughput=dl_throughput,
                                                                                   ul_throughput=ul_throughput,
                                                                                   deviation=deviation,
                                                                                   cell_ids=cell_ids,
                                                                                   duration=duration,
                                                                                   protocol=protocol,
                                                                                   udp_buffer=udp_buffer,
                                                                                   called_cell=called_cell)

        self.ssh.stop_tcpdump_collection_and_download_logs(local_path=local_pcap_path, remote_path=remote_tcpdump_path)
        self._detach_all_ues()
        self.env.verify_pcap_after_parallel_call(cell_distname=called_cell, pcap_path=local_pcap_path,
                                                 number_of_expected_attach_msgs=len(self.ues))
        self.env.clean_up_after_call(close_connection_to_bts=False)

    @log_input_and_output
    def start_data_transfer_in_background(
            self, direction, duration, throughput, protocol="udp", udp_buffer="4M",
            prepare_cells_to_call=True, called_cell=None, cells_to_ues=None, ignored_cells_on_preparation=None,
            linux_congestion=None
    ):
        """
        Method responsible for running L3 call procedure in background (in chosen direction(s)).
        'wait_for_data_transfer_to_end' method should be called after to verify L3 call procedure results.

        :param called_cell: configuration distname of cell for which L3 call will be performed
        :type called_cell: str
        :param cells_to_ues: pairs of configuration distnames of cells and serial numbers of
                             UEs that will be attached to this cell e.g
                             {"MRBTS-1/NRCELL-1": "SN1234", "MRBTS-1/LNCEL-1": "SN432"}
        :type cells_to_ues: dict
        :param direction: direction in which data transfer should be performed, 'UL', 'DL' or 'UL_DL'
        :type direction: str
        :param duration: duration of data transfer test, i.e. '30s'
        :type duration: str
        :param throughput: dictionary containing information about max tputs for each cell along with deviation
            For example:
                    throughputs = {
                                     '827736065':
                                          {
                                              'throughput':
                                                  {
                                                      'downlink': '100 Mbits/sec',
                                                      'uplink': '15 Mbits/sec'
                                                  },
                                              'deviation': '90%'
                                          },
                                    }
        :type throughput: dict
        :param protocol: data transfer protocol; defaults to udp.
        :type protocol: str
        :param udp_buffer: monitoring data buffer; defaults to 4M.
        :type udp_buffer: str
        :param prepare_cells_to_call: should environment be prepared to call, if so, all cells
                                      apart from the called one will be either barred or blocked
        :type prepare_cells_to_call: bool
        :param ignored_cells_on_preparation: SHOULD BE USED WITH `prepare_cells_to_call` set to True!
                                             list of cells CONFIGURATION distnames that should be ignored during
                                             L3 Call not called cells preparation procedure and not be blocked/barred
        :type ignored_cells_on_preparation: list[str]
        :param linux_congestion: option "-Z" for iperf2. TCP congestion algorithm (Linux and FreeBSD only),
                                 defaults to None
        :type linux_congestion: str
        """
        self._validate_called_cell_or_cells_to_ues(called_cell=called_cell, cells_to_ues=cells_to_ues)
        self._validate_data_transfer_direction(direction=direction)
        self.env.called_cells_distnames = [called_cell] if called_cell else list(cells_to_ues.keys())
        if ignored_cells_on_preparation:
            self.env.ignored_cells_distnames = ignored_cells_on_preparation
        cell_ids = self.env.cell_ids

        if prepare_cells_to_call:
            self.env.prepare_setup_to_call()

        self._dt_variables = self._prepare_data_transfer_variables_when_calling_more_than_one_cell(
            called_cells_distnames=self.env.called_cells_distnames,
            cell_ids=cell_ids,
            throughput=throughput
        )
        log_to_console("DT VARIABLES: {}".format(self._dt_variables))

        if called_cell:
            self._start_background_data_transfer_to_selected_cell(called_cell=called_cell, direction=direction,
                                                                  duration=duration, protocol=protocol,
                                                                  udp_buffer=udp_buffer,
                                                                  linux_congestion=linux_congestion)
        elif cells_to_ues:
            self._start_background_data_transfer_to_selected_cells_using_selected_ues(cells_to_ues=cells_to_ues,
                                                                                      direction=direction,
                                                                                      duration=duration,
                                                                                      protocol=protocol,
                                                                                      udp_buffer=udp_buffer,
                                                                                      linux_congestion=linux_congestion)

    @log_input_and_output
    def wait_for_background_data_transfer_to_end(self, called_cell=None, cells_to_ues=None):
        """
        Waits for background data transfer (that's started by 'start_data_transfer_in_background' method) to end.
        Method is responsible performing UE detach, stopping log collection and verifying L3 call procedure results.

        :param called_cell: configuration distname of cell for which L3 call was performed on.
        :type called_cell: str
        :param cells_to_ues: dictionary containing information about cells and UEs that were used for L3 call
        :type cells_to_ues: dict
        """
        self._validate_called_cell_or_cells_to_ues(called_cell=called_cell, cells_to_ues=cells_to_ues)
        log_to_console("Waiting for data transfer to finish on all UEs...")
        if called_cell:
            self._wait_for_data_transfer_to_selected_cell_end(called_cell=called_cell)
        elif cells_to_ues:
            self._wait_for_data_transfer_to_selected_cells_using_selected_ues_end(cells_to_ues=cells_to_ues)

    @log_input_and_output
    def make_l3_call_on_selected_cells_using_selected_ues(self, cells_to_ues, duration, throughput, protocol,
                                                          udp_buffer="4M", prepare_cells_to_call=True,
                                                          attach_should_be_possible=True,
                                                          ignored_cells_on_preparation=None):
        """
        Method responsible for performing L3 call procedure i.e. performing attach and
        testing data transfer to pairs of cells and UEs given by cells_to_ues parameter

        :param cells_to_ues: pairs of configuration IDs of cells and serial numbers
                of UEs that will be attached to them e.g: {"MRBTS-1/NRCELL-1": "SN1234", "MRBTS-1/LNCEL-1": "SN432"}
        :type cells_to_ues: dict(str, str)
        :param duration: duration of data transfer test (one for both directions), i.e. '30s', 30
        :type duration: Union[str, int]
        :param throughput: dictionary containing information about max tputs for each cell along with deviation
            For example:
                    throughputs = {
                                     '827736065':
                                          {
                                              'throughput':
                                                  {
                                                      'downlink': '100 Mbits/sec',
                                                      'uplink': '15 Mbits/sec'
                                                  },
                                              'deviation': '90%'
                                          },
                                    }
        :type throughput: dict
        :param protocol: data transfer protocol; defaults to udp.
        :type protocol: str
        :param udp_buffer: monitoring data buffer; defaults to 4M.
        :type udp_buffer: str
        :param prepare_cells_to_call: should environment be prepared to call, if so, all cells
                                      apart from the called one will be barred
        :type prepare_cells_to_call: bool
        :param attach_should_be_possible: stating if attach to selected cells should succeed
        :type attach_should_be_possible: bool, defaults to True
        :param ignored_cells_on_preparation: SHOULD BE USED WITH `prepare_cells_to_call` set to True!
                                             list of cells CONFIGURATION distnames that should be ignored during
                                             L3 Call not called cells preparation procedure and not be blocked/barred
        :type ignored_cells_on_preparation: list[str]
        """
        self.env.called_cells_distnames = list(cells_to_ues.keys())
        if ignored_cells_on_preparation:
            self.env.ignored_cells_distnames = ignored_cells_on_preparation
        cell_ids = self.env.cell_ids

        if prepare_cells_to_call:
            self.env.prepare_setup_to_call()

        local_pcap_path = self.logs_path + "/log_multi_cell_multi_ue.pcap"
        remote_tcpdump_path = self.ssh.start_tcpdump_and_get_filepath()

        data_transfer_variables = self._prepare_data_transfer_variables_when_calling_more_than_one_cell(
            called_cells_distnames=self.env.called_cells_distnames,
            cell_ids=cell_ids,
            throughput=throughput
        )

        if attach_should_be_possible:
            self._attach_multiple_ues_to_multiple_cells_and_test_data_transfer(
                data_transfer_variables=data_transfer_variables,
                cell_ids=cell_ids,
                cells_to_ues=cells_to_ues,
                duration=duration,
                protocol=protocol,
                udp_buffer=udp_buffer
            )
        else:
            for ue in self.ues:
                if ue.serial_number in cells_to_ues.values():
                    self._perform_attach(attach_should_be_possible=False, ue=ue)

        self.ssh.stop_tcpdump_collection_and_download_logs(local_path=local_pcap_path, remote_path=remote_tcpdump_path)
        self._detach_all_ues()
        for called_cell in self.env.called_cells_distnames:
            self.env.verify_pcap(cell_distname=called_cell,
                                 pcap_path=local_pcap_path,
                                 attach_should_be_possible=attach_should_be_possible)

        log_to_console("Success! L3 Call procedure executed properly on "
                       "each of the cell-UE pairs: {}".format(cells_to_ues))
        self.env.clean_up_after_call(close_connection_to_bts=False)

    def make_l3_call_on_supercell(self, called_supercell, throughputs, duration, protocol, udp_buffer,
                                  attach_should_be_possible=True, prepare_cells_to_call=True,
                                  ignored_cells_on_preparation=None):
        """
        Executes L3 call procedure on each of the called_supercell's subcells.
        :param called_supercell: configuration distname of supercell for which L3 call will be performed
        :type called_supercell: str
        :param throughputs: dictionary containing information about max tputs for each cell along with deviation
            For example:
                    throughputs = {
                                     '827736065':
                                          {
                                              'throughput':
                                                  {
                                                      'downlink': '100 Mbits/sec',
                                                      'uplink': '15 Mbits/sec'
                                                  },
                                              'deviation': '90%'
                                          },
                                    }
        :type throughputs: dict
        :param duration: duration of data transfer test (one for both directions), i.e. '30s', 30
        :type duration: Union[str, int]
        :param protocol: data transfer protocol; defaults to udp.
        :type protocol: str
        :param udp_buffer: monitoring data buffer; defaults to 4M.
        :type udp_buffer: str
        :param attach_should_be_possible: stating if attach to called_supercell should succeed
        :type attach_should_be_possible: bool
        :param prepare_cells_to_call: should environment be prepared to call, if so, all cells
                                      apart from the called one will be either barred or blocked
        :type prepare_cells_to_call: bool
        :param ignored_cells_on_preparation: SHOULD BE USED WITH `prepare_cells_to_call` set to True!
                                             list of cells CONFIGURATION distnames that should be ignored during
                                             L3 Call not called cells preparation procedure and not be blocked/barred
        :type ignored_cells_on_preparation: list[str]
        """
        number_of_super_subcells = self.env.get_number_of_super_subcells(cell_distname=called_supercell)
        self.env.called_cells_distnames = [called_supercell]
        if ignored_cells_on_preparation:
            self.env.ignored_cells_distnames = ignored_cells_on_preparation
        cell_id = self.env.cell_ids

        if prepare_cells_to_call:
            self.env.prepare_setup_to_call()

        if attach_should_be_possible:
            for subcell_id in range(number_of_super_subcells):
                attenuation_ports = self._attenuator.port_range.copy()
                called_subcell_info = self._attenuator.config[called_supercell]["Subcell-{}".format(subcell_id)]
                ports_and_on_values = {config["port"]: config["ON"] for config in called_subcell_info}

                for port, value_db in ports_and_on_values.items():
                    self._attenuator.set_attenuation_on_port(port=port, value_db=value_db)
                    attenuation_ports.remove(port)

                self._set_chosen_attenuation_mode_on_chosen_port_numbers(mode="OFF", ports=attenuation_ports)
                self._set_proper_ue_settings_before_attach(
                    throughput=throughputs,
                    cell_id=cell_id[called_supercell]["{}_cell".format(self.node)])

                self._attach_super_subcell_and_test_data_transfer(
                    cell_id=cell_id[called_supercell]["{}_cell".format(self.node)],
                    subcell_id=subcell_id,
                    cell_distname=called_supercell,
                    throughputs=throughputs,
                    duration=duration,
                    protocol=protocol,
                    udp_buffer=udp_buffer)
        else:
            self._set_all_attenuator_ports_to_chosen_mode(mode="ON")
            self._make_l3_call_attach_should_not_be_possible(called_cell=called_supercell,
                                                             prepare_cells_to_call=prepare_cells_to_call,
                                                             ignored_cells_on_preparation=ignored_cells_on_preparation)
        self.env.clean_up_after_call(close_connection_to_bts=False)

    def make_l3_call_on_iot_cell(self, called_cell, duration, attach_should_be_possible=True,
                                 prepare_cells_to_call=True, ignored_cells_on_preparation=None):
        """
        Executes L3 call procedure on given IoT cell and verifies ping test from app server to attached UE.
        :param called_cell: configuration distname of IoT cell for which L3 call will be performed
        :type called_cell: str
        :param duration: duration of data transfer test (one for both directions), i.e. '30s', 30
        :type duration: Union[str, int]
        :param attach_should_be_possible: stating if attach to called_cell should succeed
        :type attach_should_be_possible: bool
        :param prepare_cells_to_call: should environment be prepared to call, if so, all cells
                                      apart from the called one will be either barred or blocked
        :type prepare_cells_to_call: bool
        :param ignored_cells_on_preparation: SHOULD BE USED WITH `prepare_cells_to_call` set to True!
                                             list of cells CONFIGURATION distnames that should be ignored during
                                             L3 Call not called cells preparation procedure and not be blocked/barred
        :type ignored_cells_on_preparation: list[str]
        """
        if self.env.is_callable(cell_distname=called_cell):
            if attach_should_be_possible:
                self._make_iot_l3_call_attach_should_be_possible(called_cell=called_cell,
                                                                 duration=duration,
                                                                 prepare_cells_to_call=prepare_cells_to_call,
                                                                 ignored_cells_on_preparation=ignored_cells_on_preparation)
            else:
                self._make_iot_l3_call_attach_should_not_be_possible(called_cell=called_cell,
                                                                     prepare_cells_to_call=prepare_cells_to_call,
                                                                     ignored_cells_on_preparation=ignored_cells_on_preparation)
        else:
            log_warning("Given called_cell {} is not callable, "
                        "L3 Call procedure will NOT be performed!".format(called_cell))

    def make_l3_call_on_selected_iot_cells_using_selected_ues(self, cells_to_ues, duration, attach_should_be_possible=True,
                                                              prepare_cells_to_call=True, ignored_cells_on_preparation=None):
        """
        Method responsible for performing L3 call procedure i.e. performing attach and
        verifying ping test from app server to UEs attached into specified IoT cells given by cells_to_ues parameter
        :param cells_to_ues: pairs of configuration distnames of IoT cells and serial numbers
        of UEs that will be attached to them e.g: {"MRBTS-1/LNCEL-1": "SN1234", "MRBTS-1/LNCEL-2": "SN432"}
        :type cells_to_ues: dict(str, str)
        :param duration: duration of data transfer test (one for both directions), i.e. '30s', 30
        :type duration: Union[str, int]
        :param attach_should_be_possible: stating if attach to called_cell should succeed
        :type attach_should_be_possible: bool
        :param prepare_cells_to_call: should environment be prepared to call, if so, all cells
                                      apart from the called one will be either barred or blocked
        :type prepare_cells_to_call: bool
        :param ignored_cells_on_preparation: SHOULD BE USED WITH `prepare_cells_to_call` set to True!
                                             list of cells CONFIGURATION distnames that should be ignored during
                                             L3 Call not called cells preparation procedure and not be blocked/barred
        :type ignored_cells_on_preparation: list[str]
        """
        self.env.called_cells_distnames = list(cells_to_ues.keys())
        if ignored_cells_on_preparation:
            self.env.ignored_cells_distnames = ignored_cells_on_preparation
        cell_ids = self.env.cell_ids

        if prepare_cells_to_call:
            self.env.prepare_setup_to_call()

        local_pcap_path = self.logs_path + "/log_multi_iot_cell_multi_ue.pcap"
        remote_tcpdump_path = self.ssh.start_tcpdump_and_get_filepath()

        if attach_should_be_possible:
            self._attach_multiple_ues_to_multiple_iot_cells_and_verify_ping(
                cells_to_ues=cells_to_ues,
                cell_ids=cell_ids,
                duration=duration
            )
        else:
            for ue in self.ues:
                if ue.serial_number in cells_to_ues.values():
                    self._perform_attach(attach_should_be_possible=False, ue=ue)

        self.ssh.stop_tcpdump_collection_and_download_logs(local_path=local_pcap_path, remote_path=remote_tcpdump_path)
        self._detach_all_ues()
        for called_cell in self.env.called_cells_distnames:
            self.env.verify_pcap(cell_distname=called_cell,
                                 pcap_path=local_pcap_path,
                                 attach_should_be_possible=attach_should_be_possible)

        log_to_console("Success! L3 Call procedure executed properly on "
                       "each of the IoT cell-UE pairs: {}".format(cells_to_ues))

    def get_average_throughput_during_background_l3_call(self, called_cell=None, cells_to_ues=None):
        """
        Gets average throughput during background L3 call procedure
        (that's started by 'start_data_transfer_in_background' method).
        Average throughput is calculated without stopping the transfer.
        :param called_cell: configuration distname of cell for which L3 call was performed on.
        :type called_cell: str
        :param cells_to_ues: dictionary containing information about cells and UEs that were used for L3 call
        :type cells_to_ues: dict
        :return: dictionary containing information about average throughput for each UE in each direction
        :rtype: dict
        """
        self._validate_called_cell_or_cells_to_ues(called_cell=called_cell, cells_to_ues=cells_to_ues)
        for ue in self.ues:
            for direction in self._dt_names[ue.alias].keys():
                tput_avrg = ue.get_average_throughput(dt_name=self._dt_names[ue.alias][direction])
                if cells_to_ues:
                    self._avrg_tput_info[ue.serial_number][ue.cell.split('/')[-1]][direction] = tput_avrg
                else:
                    self._avrg_tput_info[ue.serial_number][called_cell.split('/')[-1]][direction] = tput_avrg
        return self._avrg_tput_info

    def verify_if_average_throughput_is_within_deviation(self, called_cell=None, cells_to_ues=None):
        """
        Verifies if average throughput during background L3 call procedure
        calculated with `get_average_throughput_during_background_l3_call` method is within deviation.
        :param called_cell: configuration distname of cell for which L3 call was performed on.
        :type called_cell: str
        :param cells_to_ues: dictionary containing information about cells and UEs that were used for L3 call
        :type cells_to_ues: dict
        :raises AssertionError: if average throughput is not within deviation
        """
        self._validate_called_cell_or_cells_to_ues(called_cell=called_cell, cells_to_ues=cells_to_ues)
        for ue in self.ues:
            cell_distname = called_cell if called_cell else ue.cell
            cell_name = self._get_cell_name(ue=ue, called_cell=called_cell)
            deviation = self._get_deviation(cell_distname=cell_distname)

            for direction in ["dl", "ul"]:
                try:
                    tput = float(self._avrg_tput_info[ue.serial_number][cell_name][direction].split(" ")[0])
                    expected_tput = self._get_expected_tput(cell_distname=cell_distname,
                                                            direction=direction)
                    expected_min = expected_tput - (expected_tput * deviation / 100)
                    expected_max = expected_tput + (expected_tput * deviation / 100)

                    if not expected_min <= tput <= expected_max:
                        error_msg = (
                            f"Average throughput for UE with SN {ue.serial_number} in direction {direction} "
                            f"is not within deviation! Expected: {expected_tput} +/- {deviation}%, got: "
                            f"{self._avrg_tput_info[ue.serial_number][cell_name][direction]}")
                        raise AssertionError(error_msg)
                except KeyError:
                    pass

        log_result("All throughput values are within deviation!")

    def stop_background_l3_call_and_verify_results(self, called_cell=None, cells_to_ues=None,
                                                   skip_results_verification=False):
        """
        Stops background L3 call procedure (that was started by 'start_data_transfer_in_background' method)
        and verifies average throughput values.
        :param called_cell: configuration distname of cell for which L3 call was performed on.
        :type called_cell: str
        :param cells_to_ues: dictionary containing information about cells and UEs that were used for L3 call
        :type cells_to_ues: dict
        :param skip_results_verification: True if throughput results verification should be skipped after background
                                          L3 call stopping, False otherwise. Defaults to False
        :type skip_results_verification: bool
        """
        self._validate_called_cell_or_cells_to_ues(called_cell=called_cell, cells_to_ues=cells_to_ues)
        if called_cell:
            self._stop_background_l3_call_and_verify_results_for_selected_cell(
                called_cell=called_cell, skip_results_verification=skip_results_verification)
        elif cells_to_ues:
            self._stop_background_l3_call_and_verify_results_for_selected_ue_and_cell_pair(
                cells_to_ues=cells_to_ues, skip_results_verification=skip_results_verification)
